function PageHeader({ eyebrow, title, description, children }: { eyebrow?: string; title: string; description?: string; children?: ReactNode }) {
  return <div className="bg-slate-50 border-b border-slate-100"><div className="section-container py-12 md:py-16"><div className="flex flex-col md:flex-row md:items-end md:justify-between gap-6"><div><div className="flex items-center gap-2 text-sm font-semibold text-brand-700 mb-3">{eyebrow && <><span className="w-2 h-2 rounded-full bg-brand-500" />{eyebrow}</>}</div><h1 className="text-3xl sm:text-4xl font-bold tracking-tight">{title}</h1>{description && <p className="mt-3 max-w-2xl text-slate-600 leading-7">{description}</p>}</div>{children}</div></div></div>;
}
function SectionTitle({ icon: Icon, title, description, action }: { icon: typeof Sparkles; title: string; description?: string; action?: ReactNode }) { return <div className="flex items-start justify-between gap-4 mb-6"><div className="flex gap-3"><span className="w-10 h-10 rounded-xl bg-brand-50 text-brand-600 flex items-center justify-center flex-shrink-0"><Icon size={20} /></span><div><h2 className="text-lg font-bold">{title}</h2>{description && <p className="text-sm text-slate-500 mt-1">{description}</p>}</div></div>{action}</div>; }
function DemoBadge() { return <span className="badge bg-brand-50 text-brand-700"><Sparkles size={12} /> Demo AI Output</span>; }
function StatCard({ icon: Icon, label, value, detail, tone = 'brand' }: { icon: typeof Sparkles; label: string; value: string; detail: string; tone?: 'brand' | 'accent' | 'warning' | 'success' }) { const colors = { brand: 'bg-brand-50 text-brand-600', accent: 'bg-accent-50 text-accent-600', warning: 'bg-warning-50 text-warning-600', success: 'bg-success-50 text-success-600' }; return <div className="card p-5"><div className="flex items-start justify-between"><span className={`w-10 h-10 rounded-xl flex items-center justify-center ${colors[tone]}`}><Icon size={20} /></span><TrendingUp size={16} className="text-success-600" /></div><p className="mt-5 text-2xl font-bold tracking-tight">{value}</p><p className="text-sm font-medium text-slate-700 mt-1">{label}</p><p className="text-xs text-slate-400 mt-2">{detail}</p></div>; }
function EmptyState({ icon: Icon, title, description, action }: { icon: typeof FileText; title: string; description: string; action?: ReactNode }) { return <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50/60 p-8 text-center"><span className="mx-auto w-12 h-12 rounded-2xl bg-white shadow-soft text-slate-400 flex items-center justify-center"><Icon size={22} /></span><h3 className="mt-4 font-bold text-slate-800">{title}</h3><p className="mt-2 text-sm text-slate-500 max-w-sm mx-auto">{description}</p>{action && <div className="mt-5">{action}</div>}</div>; }

function Home() { const { navigate } = useRouter(); const features = [{ icon: Wand2, title: 'AI-Powered Writing', text: 'Improve summaries and experience descriptions while keeping your information authentic.' }, { icon: Target, title: 'ATS Optimization', text: 'Compare your resume with a target job and find relevant, honest improvement opportunities.' }, { icon: FileCheck2, title: 'Professional Templates', text: 'Choose from clean, readable designs made for modern hiring workflows.' }, { icon: ShieldCheck, title: 'Human-Controlled AI', text: 'Review, edit, approve, or reject every AI suggestion before it becomes yours.' }]; return <><section className="relative overflow-hidden bg-slate-950 text-white"><div className="absolute inset-0 bg-[radial-gradient(circle_at_75%_20%,rgba(37,99,235,0.22),transparent_35%),radial-gradient(circle_at_10%_80%,rgba(13,148,136,0.14),transparent_30%)]" /><div className="section-container relative grid lg:grid-cols-[1.05fr_.95fr] gap-12 items-center py-20 md:py-28"><div className="animate-fade-in-up"><span className="badge bg-white/10 text-brand-200 border border-white/10"><Sparkles size={13} /> Career clarity, crafted with care</span><h1 className="mt-6 text-4xl sm:text-5xl lg:text-6xl font-bold leading-[1.08] tracking-tight text-white text-balance">Build a stronger resume. <span className="text-brand-300">Get closer</span> to your next opportunity.</h1><p className="mt-6 text-lg text-slate-300 leading-8 max-w-xl">Create a professional, ATS-friendly resume with AI-powered guidance while keeping you in control of your information.</p><div className="mt-8 flex flex-col sm:flex-row gap-3"><button className="btn-primary bg-brand-500 hover:bg-brand-400" onClick={() => navigate('builder')}>Build My Resume <ArrowRight size={17} /></button><button className="inline-flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg border border-white/20 text-white font-semibold hover:bg-white/10 transition-colors" onClick={() => navigate('assistant')}><MessageCircle size={17} /> Try AI Career Assistant</button></div><div className="mt-9 flex flex-wrap gap-x-5 gap-y-2 text-sm text-slate-400"><span className="flex items-center gap-2"><Check size={15} className="text-accent-400" /> No fabricated facts</span><span className="flex items-center gap-2"><Check size={15} className="text-accent-400" /> Review every suggestion</span><span className="flex items-center gap-2"><Check size={15} className="text-accent-400" /> Local demo profile</span></div></div><div className="relative animate-fade-in"><div className="absolute -inset-6 bg-brand-500/10 blur-3xl rounded-full" /><div className="relative rounded-2xl border border-white/10 bg-white/[0.06] backdrop-blur p-4 shadow-elevated"><div className="flex items-center justify-between px-3 py-2"><div className="flex gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-error-400" /><span className="w-2.5 h-2.5 rounded-full bg-warning-400" /><span className="w-2.5 h-2.5 rounded-full bg-success-400" /></div><span className="text-xs text-slate-500">Resume workspace</span></div><div className="bg-white rounded-xl p-6 text-slate-900 mt-2"><div className="flex justify-between border-b border-slate-100 pb-5"><div><div className="h-3 bg-brand-600 rounded w-36" /><div className="h-2 bg-slate-200 rounded w-28 mt-2" /></div><div className="text-right space-y-1"><div className="h-2 bg-slate-200 rounded w-20" /><div className="h-2 bg-slate-200 rounded w-24" /></div></div><div className="grid grid-cols-[1fr_2fr] gap-5 mt-5"><div className="space-y-4"><div><div className="h-2 bg-brand-100 rounded w-20" /><div className="h-1.5 bg-slate-100 rounded w-24 mt-2" /><div className="h-1.5 bg-slate-100 rounded w-20 mt-1.5" /><div className="h-1.5 bg-slate-100 rounded w-16 mt-1.5" /></div><div><div className="h-2 bg-brand-100 rounded w-20" /><div className="flex flex-wrap gap-1.5 mt-2"><i className="h-4 w-10 rounded bg-slate-100" /><i className="h-4 w-12 rounded bg-slate-100" /><i className="h-4 w-14 rounded bg-slate-100" /><i className="h-4 w-10 rounded bg-slate-100" /></div></div></div><div><div className="h-2 bg-brand-100 rounded w-28" /><div className="h-2 bg-slate-200 rounded w-full mt-3" /><div className="h-1.5 bg-slate-100 rounded w-11/12 mt-2" /><div className="h-1.5 bg-slate-100 rounded w-10/12 mt-2" /><div className="h-2 bg-brand-100 rounded w-24 mt-6" /><div className="h-1.5 bg-slate-100 rounded w-full mt-3" /><div className="h-1.5 bg-slate-100 rounded w-9/12 mt-2" /><div className="h-1.5 bg-slate-100 rounded w-11/12 mt-2" /></div></div></div><div className="absolute -right-4 bottom-12 bg-white rounded-xl shadow-elevated p-4 w-48 text-slate-800"><div className="flex items-center gap-2"><span className="w-8 h-8 rounded-lg bg-success-100 text-success-700 flex items-center justify-center"><CheckCircle2 size={17} /></span><div><p className="text-xs text-slate-500">ATS estimate</p><p className="font-bold">82 / 100</p></div></div><div className="h-1.5 bg-slate-100 rounded-full mt-3"><div className="h-full bg-success-500 rounded-full w-[82%]" /></div></div></div></div></div></section><section className="section-container py-20"><div className="text-center max-w-2xl mx-auto"><span className="badge bg-brand-50 text-brand-700">Everything you need to move forward</span><h2 className="mt-4 text-3xl font-bold">Your career story, made stronger</h2><p className="mt-3 text-slate-500 leading-7">Thoughtful tools for every part of the application journey — with your judgment at the center.</p></div><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-5 mt-12">{features.map((f) => <div key={f.title} className="card p-6 hover:-translate-y-1 transition-transform"><span className="w-11 h-11 rounded-xl bg-brand-50 text-brand-600 flex items-center justify-center"><f.icon size={21} /></span><h3 className="mt-5 font-bold">{f.title}</h3><p className="mt-2 text-sm text-slate-500 leading-6">{f.text}</p></div>)}</div></section><section className="bg-slate-50 border-y border-slate-100"><div className="section-container py-20"><div className="text-center"><span className="badge bg-accent-50 text-accent-700">A clearer path</span><h2 className="mt-4 text-3xl font-bold">From blank page to ready to apply</h2></div><div className="mt-12 grid grid-cols-2 md:grid-cols-7 gap-4 items-center">{['Your Information','AI Assistance','Review','Improve','ATS Check','Resume','Export'].map((item, i) => <div key={item} className="flex md:flex-col items-center gap-2 text-center"><div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold ${i === 6 ? 'bg-brand-600 text-white' : 'bg-white text-brand-700 border border-slate-200 shadow-soft'}`}>{i + 1}</div><p className="text-xs font-semibold text-slate-600">{item}</p>{i < 6 && <ArrowRight size={15} className="hidden md:block text-slate-300 absolute translate-x-[85px]" />}</div>)}</div></div></section><section className="section-container py-20"><div className="rounded-3xl bg-brand-700 px-7 py-12 md:p-14 text-center text-white relative overflow-hidden"><div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_50%_20%,white,transparent_50%)]" /><div className="relative"><h2 className="text-3xl font-bold text-white">Your next opportunity starts with clarity.</h2><p className="mt-3 text-brand-100 max-w-xl mx-auto">Build a resume that reflects your real experience, your strengths, and where you want to go.</p><button className="mt-7 inline-flex items-center gap-2 px-6 py-3 bg-white text-brand-700 font-bold rounded-lg hover:bg-brand-50 transition-colors" onClick={() => navigate('builder')}>Start Building Free <ArrowRight size={17} /></button></div></div></section></>; }

function Dashboard() { const { data, completionPercentage } = useResume(); const { navigate } = useRouter(); const quick = [{ icon: Pencil, title: 'Continue Resume', text: 'Pick up where you left off', route: 'builder' as PageRoute }, { icon: Wand2, title: 'Improve Summary', text: 'Make your introduction stronger', route: 'builder' as PageRoute }, { icon: Search, title: 'Analyze Job Description', text: 'Find the right keywords', route: 'builder' as PageRoute }, { icon: BarChart3, title: 'Check ATS Score', text: 'See how aligned you are', route: 'ats' as PageRoute }, { icon: MessageCircle, title: 'Ask Career Assistant', text: 'Get practical guidance', route: 'assistant' as PageRoute }, { icon: FileText, title: 'Preview Resume', text: 'See your finished resume', route: 'builder' as PageRoute }]; return <><PageHeader eyebrow="Your workspace" title={`Good progress, ${data.personal.fullName || 'there'}.`} description="A quick view of your resume journey. This is your local Demo Profile — replace it with your own information anytime." /> <main className="section-container py-10"><div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-7"><div><span className="badge bg-warning-50 text-warning-700"><Sparkles size={12} /> Demo Profile</span><h2 className="mt-2 text-xl font-bold">Resume overview</h2></div><button onClick={() => navigate('builder')} className="btn-primary"><Pencil size={16} /> Edit Resume</button></div><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-5"><StatCard icon={FileText} label="Resume completion" value={`${completionPercentage}%`} detail="Keep building your story" /><StatCard icon={BarChart3} label="ATS score" value={data.atsResult ? `${data.atsResult.score}/100` : '—'} detail={data.atsResult ? 'Latest estimate' : 'Run an analysis'} tone="success" /><StatCard icon={ClipboardCheck} label="Suggestions reviewed" value={String((data.summaryAiAccepted ? 1 : 0) + data.experience.filter((e) => e.aiAccepted).length)} detail="Human-approved changes" tone="accent" /><StatCard icon={Clock3} label="Illustrative time saved" value="45 min" detail="Demo estimate, not a guarantee" tone="warning" /></div><div className="grid lg:grid-cols-[1.15fr_.85fr] gap-6 mt-6"><div className="card p-6"><SectionTitle icon={Zap} title="Quick actions" description="Keep your application moving." /><div className="grid sm:grid-cols-2 gap-3">{quick.map((item) => <button key={item.title} onClick={() => navigate(item.route)} className="text-left p-4 rounded-xl border border-slate-100 hover:border-brand-200 hover:bg-brand-50/50 transition-all group"><div className="flex items-center justify-between"><span className="w-9 h-9 rounded-lg bg-slate-100 text-slate-600 group-hover:bg-brand-100 group-hover:text-brand-700 flex items-center justify-center transition-colors"><item.icon size={17} /></span><ArrowRight size={16} className="text-slate-300 group-hover:text-brand-600 transition-colors" /></div><p className="mt-3 font-semibold text-sm">{item.title}</p><p className="text-xs text-slate-500 mt-1">{item.text}</p></button>)}</div></div><div className="space-y-6"><div className="card p-6"><SectionTitle icon={Target} title="Current target" /><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Target role</p><p className="mt-2 font-bold text-slate-900">{data.jobTarget.targetJobTitle || 'Not set yet'}</p>{data.jobTarget.targetCompany && <p className="text-sm text-slate-500 mt-1">{data.jobTarget.targetCompany}</p>}<button onClick={() => navigate('builder')} className="mt-4 text-sm font-semibold text-brand-700 hover:text-brand-800 flex items-center gap-1">Update target <ArrowRight size={14} /></button></div></div><div className="card p-6"><SectionTitle icon={FileCheck2} title="Current template" /><div className="flex items-center gap-4"><div className="w-20 h-24 rounded-lg bg-white border border-slate-200 shadow-soft p-2"><div className="h-1.5 bg-brand-600 rounded w-10" /><div className="h-1 bg-slate-200 rounded w-14 mt-2" /><div className="h-1 bg-slate-100 rounded w-full mt-3" /><div className="h-1 bg-slate-100 rounded w-11/12 mt-1.5" /><div className="h-1 bg-slate-100 rounded w-full mt-1.5" /></div><div><p className="font-bold capitalize">{data.template}</p><p className="text-sm text-slate-500 mt-1">Clean and professional</p><button onClick={() => navigate('templates')} className="mt-2 text-sm text-brand-700 font-semibold">Change template</button></div></div></div></div></div></main></>; }

const steps = ['Personal Details','Summary','Experience','Education','Skills','Job Target','Review','Preview'];
function TextInput({ label, value, onChange, placeholder, type = 'text', required = false }: { label: string; value: string; onChange: (v: string) => void; placeholder?: string; type?: string; required?: boolean }) { return <label className="block"><span className="label-field">{label}{required && <span className="text-error-600 ml-1">*</span>}</span><input className="input-field" type={type} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} /></label>; }
function TextArea({ label, value, onChange, placeholder, rows = 5 }: { label: string; value: string; onChange: (v: string) => void; placeholder?: string; rows?: number }) { return <label className="block"><span className="label-field">{label}</span><textarea className="input-field resize-y" rows={rows} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} /></label>; }

function Builder() { const { data, updatePersonal, updateSummary, setImprovedSummary, acceptSummaryAI, addExperience, updateExperience, removeExperience, setImprovedExperience, acceptExperienceAI, addEducation, updateEducation, removeEducation, addCertificate, updateCertificate, removeCertificate, addProject, updateProject, removeProject, addSkill, removeSkill, updateJobTarget, setJobAnalysis, toggleChecklist, completionPercentage } = useResume(); const { navigate } = useRouter(); const [step, setStep] = useState(0); const [loading, setLoading] = useState(''); const [skillInput, setSkillInput] = useState(''); const [skillSuggestions, setSkillSuggestions] = useState<{ technical: string[]; soft: string[] }>({ technical: [], soft: [] }); const [error, setError] = useState(''); const [previewOpen, setPreviewOpen] = useState(false); const personal = data.personal; const run = async (key: string, fn: () => Promise<void>) => { setError(''); setLoading(key); try { await fn(); } catch { setError('Demo AI could not complete that suggestion. Please try again.'); } finally { setLoading(''); } }; const checklistLabels = ['I reviewed the AI-generated content.','All information is factually correct.','I did not include skills I do not possess.','I did not include qualifications I do not have.','My employment history is accurate.','My dates and contact information are correct.','I understand that ATS optimization does not guarantee employment.']; const renderStep = () => { if (step === 0) return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={UserRound} title="Personal details" description="Only include the contact information you want employers to use." /><div className="grid sm:grid-cols-2 gap-5"><TextInput label="Full name" required value={personal.fullName} onChange={(v) => updatePersonal({ ...personal, fullName: v })} placeholder="Your full name" /><TextInput label="Professional title" required value={personal.professionalTitle} onChange={(v) => updatePersonal({ ...personal, professionalTitle: v })} placeholder="e.g. Junior Designer" /><TextInput label="Email" required type="email" value={personal.email} onChange={(v) => updatePersonal({ ...personal, email: v })} placeholder="you@example.com" /><TextInput label="Phone" value={personal.phone} onChange={(v) => updatePersonal({ ...personal, phone: v })} placeholder="+1 555 000 0000" /><TextInput label="Location" value={personal.location} onChange={(v) => updatePersonal({ ...personal, location: v })} placeholder="City, Country" /><TextInput label="LinkedIn" value={personal.linkedin} onChange={(v) => updatePersonal({ ...personal, linkedin: v })} placeholder="linkedin.com/in/yourname" /><TextInput label="Portfolio / website" value={personal.portfolio} onChange={(v) => updatePersonal({ ...personal, portfolio: v })} placeholder="yourwebsite.com" /></div><div className="mt-6 p-4 rounded-xl bg-brand-50 border border-brand-100 flex gap-3 text-sm text-brand-800"><Info size={18} className="flex-shrink-0 mt-0.5" /><p>We don’t require a street address, date of birth, photo, or other unnecessary personal information.</p></div></div>; if (step === 1) return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={Wand2} title="Professional summary" description="Write your own summary, then use Demo AI to improve clarity without adding facts." /><TextArea label="Your summary" value={data.summary} onChange={updateSummary} placeholder="Describe your experience, strengths, and career direction..." rows={7} /><div className="mt-5 flex items-center justify-between"><DemoBadge /><button className="btn-primary text-sm" disabled={!data.summary.trim() || loading === 'summary'} onClick={() => run('summary', async () => setImprovedSummary(await improveSummary(data.summary)))}>{loading === 'summary' ? <Loader2 size={16} className="animate-spin" /> : <Wand2 size={16} />} Improve with AI</button></div>{data.improvedSummary && <div className="grid md:grid-cols-2 gap-4 mt-6"><div className="rounded-xl border border-slate-200 p-5"><p className="text-xs uppercase tracking-wider font-bold text-slate-400">Original</p><p className="mt-3 text-sm text-slate-600 leading-6">{data.summary}</p></div><div className="rounded-xl border border-brand-200 bg-brand-50/40 p-5"><div className="flex items-center justify-between"><p className="text-xs uppercase tracking-wider font-bold text-brand-700">AI suggestion</p><DemoBadge /></div><textarea className="input-field mt-3 bg-white" rows={6} value={data.improvedSummary} onChange={(e) => setImprovedSummary(e.target.value)} /><div className="flex gap-2 mt-4"><button className="btn-primary text-sm" onClick={() => { updateSummary(data.improvedSummary ?? ''); acceptSummaryAI(true); }}>Accept</button><button className="btn-secondary text-sm" onClick={() => { setImprovedSummary(null); acceptSummaryAI(false); }}>Reject</button></div></div></div>}</div>; if (step === 2) return <ExperienceStep data={data} addExperience={addExperience} updateExperience={updateExperience} removeExperience={removeExperience} setImprovedExperience={setImprovedExperience} acceptExperienceAI={acceptExperienceAI} loading={loading} run={run} />; if (step === 3) return <EducationStep data={data} addEducation={addEducation} updateEducation={updateEducation} removeEducation={removeEducation} addCertificate={addCertificate} updateCertificate={updateCertificate} removeCertificate={removeCertificate} addProject={addProject} updateProject={updateProject} removeProject={removeProject} />; if (step === 4) return <SkillsStep data={data} skillInput={skillInput} setSkillInput={setSkillInput} addSkill={addSkill} removeSkill={removeSkill} suggest={async () => run('skills', async () => setSkillSuggestions(await suggestSkills(data.skills, data.jobTarget.jobDescription)))} loading={loading} suggestions={skillSuggestions} />; if (step === 5) return <JobTargetStep data={data} updateJobTarget={updateJobTarget} analyze={async () => run('job', async () => setJobAnalysis(await analyzeJobDescription(data.jobTarget.jobDescription)))} loading={loading} />; if (step === 6) return <ReviewStep data={data} checklistLabels={checklistLabels} toggleChecklist={toggleChecklist} completion={completionPercentage} />; return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={FileText} title="Preview your resume" description="See your confirmed information in a professional layout." /><ResumePreview compact /><div className="mt-6 flex flex-col sm:flex-row gap-3"><button className="btn-primary" onClick={() => setPreviewOpen(true)}><ExternalLink size={16} /> Open full preview</button><button className="btn-secondary" onClick={() => window.print()}><Printer size={16} /> Print / save PDF</button></div>{previewOpen && <PreviewModal onClose={() => setPreviewOpen(false)} />}</div>; }; return <><PageHeader eyebrow="Resume workspace" title="Build your resume" description="A focused, step-by-step workspace for creating a resume that is genuinely yours." /><main className="section-container py-8"><div className="flex items-center justify-between gap-4 mb-6"><div><span className="badge bg-warning-50 text-warning-700"><Sparkles size={12} /> Demo Profile</span><p className="text-sm text-slate-500 mt-2">Saved locally in this browser</p></div><div className="text-right"><p className="text-sm font-bold text-slate-900">{completionPercentage}% complete</p><div className="w-32 h-1.5 rounded-full bg-slate-100 mt-2"><div className="h-full rounded-full bg-brand-600 transition-all" style={{ width: `${completionPercentage}%` }} /></div></div></div><div className="card p-3 mb-6 overflow-x-auto"><div className="flex min-w-[720px] items-center">{steps.map((label, i) => <div key={label} className="flex-1 flex items-center"><button onClick={() => setStep(i)} className="flex items-center gap-2 group"><span className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${i === step ? 'bg-brand-600 text-white' : i < step ? 'bg-success-100 text-success-700' : 'bg-slate-100 text-slate-500 group-hover:bg-slate-200'}`}>{i < step ? <Check size={15} /> : i + 1}</span><span className={`text-xs font-semibold whitespace-nowrap ${i === step ? 'text-brand-700' : 'text-slate-500'}`}>{label}</span></button>{i < steps.length - 1 && <div className={`h-px flex-1 mx-2 ${i < step ? 'bg-success-300' : 'bg-slate-200'}`} />}</div>)}</div></div>{error && <div className="mb-5 p-3 rounded-lg bg-error-50 border border-error-100 text-error-700 text-sm flex items-center gap-2"><AlertCircle size={16} />{error}</div>}{renderStep()}<div className="flex items-center justify-between mt-6"><button className="btn-secondary" disabled={step === 0} onClick={() => setStep((s) => s - 1)}><ChevronLeft size={16} /> Back</button>{step === 7 ? <button className="btn-primary" onClick={() => navigate('ats')}>Continue to ATS Check <ArrowRight size={16} /></button> : <button className="btn-primary" onClick={() => setStep((s) => Math.min(7, s + 1))}>Continue <ChevronRight size={16} /></button>}</div></main></>; }

function ExperienceStep({ data, addExperience, updateExperience, removeExperience, setImprovedExperience, acceptExperienceAI, loading, run }: any) { return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={BriefcaseBusiness} title="Work experience" description="Add positions, internships, volunteering, or other relevant experience." action={<button onClick={() => addExperience()} className="btn-secondary text-sm"><Plus size={16} /> Add position</button>} />{data.experience.length === 0 ? <EmptyState icon={BriefcaseBusiness} title="No experience added yet" description="Add your first position, internship, project, or volunteering experience." action={<button className="btn-primary text-sm" onClick={() => addExperience()}><Plus size={15} /> Add position</button>} /> : <div className="space-y-6">{data.experience.map((e: any, index: number) => <div key={e.id} className="rounded-xl border border-slate-200 p-5"><div className="flex items-center justify-between mb-5"><h3 className="font-bold">Position {index + 1}</h3><button className="btn-ghost text-error-600 hover:bg-error-50 p-2" onClick={() => removeExperience(e.id)} aria-label="Remove position"><Trash2 size={16} /></button></div><div className="grid sm:grid-cols-2 gap-5"><TextInput label="Job title" value={e.jobTitle} onChange={(v) => updateExperience(e.id, { jobTitle: v })} placeholder="e.g. IT Support Intern" /><TextInput label="Company" value={e.company} onChange={(v) => updateExperience(e.id, { company: v })} placeholder="Company name" /><TextInput label="Location" value={e.location} onChange={(v) => updateExperience(e.id, { location: v })} placeholder="City or Remote" /><div className="grid grid-cols-2 gap-3"><TextInput label="Start date" type="month" value={e.startDate} onChange={(v) => updateExperience(e.id, { startDate: v })} /><TextInput label="End date" type="month" value={e.endDate} onChange={(v) => updateExperience(e.id, { endDate: v })} /></div></div><div className="mt-5"><TextArea label="Responsibilities / achievements" value={e.responsibilities} onChange={(v) => updateExperience(e.id, { responsibilities: v })} placeholder="Describe what you did. Use a new line for each bullet." rows={5} /></div><div className="mt-4 flex items-center justify-between"><DemoBadge /><button className="btn-primary text-sm" disabled={!e.responsibilities.trim() || loading === `exp-${e.id}`} onClick={() => run(`exp-${e.id}`, async () => setImprovedExperience(e.id, await improveExperience(e.responsibilities)))}>{loading === `exp-${e.id}` ? <Loader2 size={15} className="animate-spin" /> : <Wand2 size={15} />} Improve with AI</button></div>{e.improvedResponsibilities && <div className="grid md:grid-cols-2 gap-4 mt-5"><div className="p-4 rounded-xl bg-slate-50"><p className="text-xs uppercase font-bold tracking-wider text-slate-400">Original</p><p className="whitespace-pre-line text-sm leading-6 text-slate-600 mt-2">{e.responsibilities}</p></div><div className="p-4 rounded-xl bg-brand-50 border border-brand-100"><p className="text-xs uppercase font-bold tracking-wider text-brand-700">AI suggestion</p><textarea className="input-field mt-2 bg-white" rows={5} value={e.improvedResponsibilities} onChange={(ev) => setImprovedExperience(e.id, ev.target.value)} /><div className="flex gap-2 mt-3"><button className="btn-primary text-sm" onClick={() => { updateExperience(e.id, { responsibilities: e.improvedResponsibilities ?? '', aiAccepted: true }); acceptExperienceAI(e.id, true); }}>Accept</button><button className="btn-secondary text-sm" onClick={() => { setImprovedExperience(e.id, null); acceptExperienceAI(e.id, false); }}>Reject</button></div></div></div>}</div>)}</div>}</div>; }
function EducationStep({ data, addEducation, updateEducation, removeEducation, addCertificate, updateCertificate, removeCertificate, addProject, updateProject, removeProject }: any) { return <div className="space-y-6 animate-fade-in"><div className="card p-6 md:p-8"><SectionTitle icon={GraduationCap} title="Education" description="Add degrees, diplomas, school, and relevant training." action={<button onClick={() => addEducation()} className="btn-secondary text-sm"><Plus size={16} /> Add education</button>} />{data.education.length === 0 ? <EmptyState icon={GraduationCap} title="No education added yet" description="Add your education to show employers your foundation." action={<button className="btn-primary text-sm" onClick={() => addEducation()}><Plus size={15} /> Add education</button>} /> : <div className="space-y-5">{data.education.map((e: any, index: number) => <div key={e.id} className="rounded-xl border border-slate-200 p-5"><div className="flex justify-between mb-5"><h3 className="font-bold">Education {index + 1}</h3><button className="btn-ghost text-error-600 hover:bg-error-50 p-2" onClick={() => removeEducation(e.id)}><Trash2 size={16} /></button></div><div className="grid sm:grid-cols-2 gap-5"><TextInput label="Qualification" value={e.qualification} onChange={(v) => updateEducation(e.id, { qualification: v })} placeholder="e.g. Bachelor of Science" /><TextInput label="Institution" value={e.institution} onChange={(v) => updateEducation(e.id, { institution: v })} placeholder="Institution name" /><TextInput label="Location" value={e.location} onChange={(v) => updateEducation(e.id, { location: v })} placeholder="City or Remote" /><div className="grid grid-cols-2 gap-3"><TextInput label="Start date" type="month" value={e.startDate} onChange={(v) => updateEducation(e.id, { startDate: v })} /><TextInput label="End date" type="month" value={e.endDate} onChange={(v) => updateEducation(e.id, { endDate: v })} /></div></div><div className="grid md:grid-cols-2 gap-5 mt-5"><TextArea label="Description" value={e.description} onChange={(v) => updateEducation(e.id, { description: v })} rows={3} placeholder="Relevant coursework or focus" /><TextArea label="Achievements" value={e.achievements} onChange={(v) => updateEducation(e.id, { achievements: v })} rows={3} placeholder="Awards, results, activities" /></div></div>)}</div>}</div><CollectionCard title="Certificates & training" icon={FileCheck2} items={data.certificates} add={() => addCertificate()} onRemove={removeCertificate} render={(c: any) => <div className="grid sm:grid-cols-3 gap-4"><TextInput label="Certificate name" value={c.name} onChange={(v) => updateCertificate(c.id, { name: v })} placeholder="e.g. Google Analytics" /><TextInput label="Issuer" value={c.issuer} onChange={(v) => updateCertificate(c.id, { issuer: v })} placeholder="Organization" /><TextInput label="Date" type="month" value={c.date} onChange={(v) => updateCertificate(c.id, { date: v })} /></div>} /><CollectionCard title="Projects" icon={Lightbulb} items={data.projects} add={() => addProject()} onRemove={removeProject} render={(p: any) => <div className="grid md:grid-cols-2 gap-4"><TextInput label="Project name" value={p.name} onChange={(v) => updateProject(p.id, { name: v })} placeholder="Project name" /><TextInput label="Technologies" value={p.technologies} onChange={(v) => updateProject(p.id, { technologies: v })} placeholder="Tools you actually used" /><div className="md:col-span-2"><TextArea label="Description" value={p.description} onChange={(v) => updateProject(p.id, { description: v })} rows={3} placeholder="What did you build or contribute to?" /></div></div>} /></div>; }
function CollectionCard({ title, icon: Icon, items, add, onRemove, render }: any) { return <div className="card p-6 md:p-8"><SectionTitle icon={Icon} title={title} action={<button onClick={add} className="btn-secondary text-sm"><Plus size={16} /> Add</button>} />{items.length === 0 ? <p className="text-sm text-slate-500 py-3">Nothing added yet. This section is optional.</p> : <div className="space-y-4">{items.map((item: any, i: number) => <div key={item.id} className="rounded-xl border border-slate-200 p-5"><div className="flex justify-between mb-4"><span className="text-sm font-bold text-slate-700">{title.slice(0, -1)} {i + 1}</span><button className="btn-ghost text-error-600 hover:bg-error-50 p-1.5" onClick={() => onRemove(item.id)}><Trash2 size={15} /></button></div>{render(item)}</div>)}</div>}</div>; }
function SkillsStep({ data, skillInput, setSkillInput, addSkill, removeSkill, suggest, loading, suggestions }: any) { const addCustom = (category: 'technical' | 'soft') => { if (skillInput.trim()) { addSkill({ name: skillInput.trim(), category, aiSuggested: false }); setSkillInput(''); } }; return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={Zap} title="Skills" description="Add only skills you genuinely possess. AI suggestions always require your approval." /><div className="grid md:grid-cols-2 gap-6"><div><h3 className="font-bold text-sm">Technical skills</h3><div className="flex flex-wrap gap-2 mt-3">{data.skills.filter((s: any) => s.category === 'technical').map((s: any) => <span key={s.id} className="badge bg-brand-50 text-brand-700">{s.name}<button onClick={() => removeSkill(s.id)} aria-label={`Remove ${s.name}`}><X size={13} /></button></span>)}</div></div><div><h3 className="font-bold text-sm">Soft skills</h3><div className="flex flex-wrap gap-2 mt-3">{data.skills.filter((s: any) => s.category === 'soft').map((s: any) => <span key={s.id} className="badge bg-accent-50 text-accent-700">{s.name}<button onClick={() => removeSkill(s.id)} aria-label={`Remove ${s.name}`}><X size={13} /></button></span>)}</div></div></div><div className="mt-8 p-5 rounded-xl bg-slate-50"><p className="label-field">Add a custom skill</p><div className="flex flex-col sm:flex-row gap-3"><input className="input-field" value={skillInput} onChange={(e) => setSkillInput(e.target.value)} placeholder="Type a skill" /><button className="btn-secondary whitespace-nowrap" onClick={() => addCustom('technical')}><Plus size={15} /> Technical</button><button className="btn-secondary whitespace-nowrap" onClick={() => addCustom('soft')}><Plus size={15} /> Soft skill</button></div></div><div className="mt-8 border-t border-slate-100 pt-6"><div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3"><div><h3 className="font-bold">Suggest skills with AI</h3><p className="text-sm text-slate-500 mt-1">Based on your current skills and target job description only.</p></div><button className="btn-primary text-sm" onClick={suggest} disabled={loading === 'skills'}>{loading === 'skills' ? <Loader2 size={15} className="animate-spin" /> : <Sparkles size={15} />} Suggest Skills</button></div>{(suggestions.technical.length > 0 || suggestions.soft.length > 0) ? <div className="mt-5 p-4 rounded-xl bg-brand-50 border border-brand-100"><div className="flex items-center justify-between"><p className="text-sm font-bold text-brand-900">Review suggestions</p><DemoBadge /></div><div className="flex flex-wrap gap-2 mt-3">{[...suggestions.technical.map((s: string) => [s, 'technical']), ...suggestions.soft.map((s: string) => [s, 'soft'])].map(([name, category]) => <span key={name} className="badge bg-white border border-brand-200 text-slate-700">{name}<button className="text-success-700 ml-1" onClick={() => addSkill({ name, category, aiSuggested: true })}><Check size={14} /></button><button className="text-error-600" onClick={() => {}}><X size={14} /></button></span>)}</div></div> : <p className="text-sm text-slate-400 mt-4">Suggestions will appear here for you to review.</p>}</div></div>; }
function JobTargetStep({ data, updateJobTarget, analyze, loading }: any) { const a = data.jobAnalysis; return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={Target} title="Job target" description="Give CareerCraft AI a role to tailor your resume toward." /><div className="grid sm:grid-cols-2 gap-5"><TextInput label="Target job title" value={data.jobTarget.targetJobTitle} onChange={(v) => updateJobTarget({ ...data.jobTarget, targetJobTitle: v })} placeholder="e.g. Junior IT Support" /><TextInput label="Target company" value={data.jobTarget.targetCompany} onChange={(v) => updateJobTarget({ ...data.jobTarget, targetCompany: v })} placeholder="Optional" /></div><div className="mt-5"><TextArea label="Job description" value={data.jobTarget.jobDescription} onChange={(v) => updateJobTarget({ ...data.jobTarget, jobDescription: v })} placeholder="Paste the job description here..." rows={9} /></div><div className="mt-5 flex items-center justify-between"><span className="text-xs text-slate-500 flex items-center gap-1"><Info size={14} /> Analysis is a Demo AI estimate</span><button className="btn-primary" onClick={analyze} disabled={!data.jobTarget.jobDescription.trim() || loading === 'job'}>{loading === 'job' ? <Loader2 size={16} className="animate-spin" /> : <Search size={16} />} Analyze Job Description</button></div>{!data.jobTarget.jobDescription.trim() && <p className="text-xs text-warning-700 mt-3 flex items-center gap-1"><AlertCircle size={13} /> Add a job description to unlock analysis.</p>}{a && <div className="mt-8 border-t border-slate-100 pt-7"><div className="flex items-center justify-between"><h3 className="font-bold">Analysis results</h3><DemoBadge /></div><div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4 mt-5">{[['Important keywords', a.keywords, 'bg-brand-50 text-brand-700'],['Required skills', a.requiredSkills, 'bg-accent-50 text-accent-700'],['Responsibilities', a.responsibilities, 'bg-slate-100 text-slate-700'],['Qualifications', a.qualifications, 'bg-warning-50 text-warning-700'],['Technologies', a.technologies, 'bg-success-50 text-success-700'],['Soft skills', a.softSkills, 'bg-brand-50 text-brand-700']].map(([title, items, color]) => <div key={title as string} className="rounded-xl border border-slate-100 p-4"><p className="text-sm font-bold">{title as string}</p><div className="flex flex-wrap gap-1.5 mt-3">{(items as string[]).length ? (items as string[]).map((x) => <span key={x} className={`badge ${color as string}`}>{x}</span>) : <span className="text-xs text-slate-400">Not detected in this description</span>}</div></div>)}</div><div className="mt-5 p-4 rounded-xl bg-warning-50 border border-warning-200 text-sm text-warning-900 flex gap-2"><AlertCircle size={18} className="flex-shrink-0" /><p>Only include keywords and skills that genuinely apply to your experience.</p></div></div>}</div>; }
function ReviewStep({ data, checklistLabels, toggleChecklist, completion }: any) { const all = data.checklist.every(Boolean); return <div className="card p-6 md:p-8 animate-fade-in"><SectionTitle icon={ClipboardCheck} title="Review & validate" description="Your information stays yours. Confirm each item before exporting." /><div className="p-4 rounded-xl bg-warning-50 border border-warning-200 flex gap-3 text-sm text-warning-900"><ShieldCheck size={20} className="flex-shrink-0" /><p>AI-generated suggestions are recommendations, not verified facts. Always review and validate your resume before submitting it to an employer.</p></div><div className="mt-6 space-y-3">{checklistLabels.map((label: string, i: number) => <label key={label} className={`flex items-start gap-3 p-4 rounded-xl border cursor-pointer transition-colors ${data.checklist[i] ? 'bg-success-50 border-success-200' : 'border-slate-200 hover:bg-slate-50'}`}><input type="checkbox" className="mt-0.5 w-4 h-4 accent-brand-600" checked={data.checklist[i]} onChange={() => toggleChecklist(i)} /><span className="text-sm text-slate-700">{label}</span></label>)}</div><div className="mt-6 flex items-center justify-between p-4 rounded-xl bg-slate-50"><div><p className="font-bold text-sm">Export readiness</p><p className="text-xs text-slate-500 mt-1">{all ? 'Everything is confirmed.' : `${data.checklist.filter(Boolean).length} of ${checklistLabels.length} confirmations complete`}</p></div><span className={`badge ${all ? 'bg-success-100 text-success-700' : 'bg-warning-100 text-warning-700'}`}>{all ? <><CheckCircle2 size={13} /> Ready</> : <><Clock3 size={13} /> Review needed</>}</span></div></div>; }

function ResumePreview({ compact = false }: { compact?: boolean }) { const { data } = useResume(); const p = data.personal; const summary = data.summaryAiAccepted && data.improvedSummary ? data.improvedSummary : data.summary; const template = data.template; return <div id="resume-print-area" className={`bg-white text-slate-900 ${compact ? 'max-h-[680px] overflow-hidden' : ''} ${template === 'classic' ? 'font-serif' : ''}`}><div className={`p-7 sm:p-10 ${template === 'minimal' ? 'max-w-3xl mx-auto' : ''}`}><div className={`pb-5 ${template === 'modern' ? 'border-b-4 border-brand-600' : 'border-b border-slate-300'}`}><h1 className={`font-bold ${template === 'modern' ? 'text-3xl text-brand-800' : 'text-3xl'}`}>{p.fullName || 'Your Name'}</h1><p className="mt-1 text-sm font-semibold text-slate-600">{p.professionalTitle || 'Professional Title'}</p><div className="flex flex-wrap gap-x-4 gap-y-1 mt-3 text-xs text-slate-500">{[p.email, p.phone, p.location, p.linkedin, p.portfolio].filter(Boolean).map((x) => <span key={x}>{x}</span>)}</div></div>{summary && <ResumeSection title="Professional Summary"><p className="text-xs leading-5 text-slate-600">{summary}</p></ResumeSection>}{data.experience.length > 0 && <ResumeSection title="Experience">{data.experience.map((e) => <div key={e.id} className="mb-4"><div className="flex justify-between gap-4"><div><p className="text-sm font-bold">{e.jobTitle || 'Job title'}</p><p className="text-xs text-brand-700 font-semibold">{e.company || 'Company'}{e.location && ` · ${e.location}`}</p></div><span className="text-[10px] text-slate-500 whitespace-nowrap">{e.startDate} – {e.current ? 'Present' : e.endDate}</span></div><p className="whitespace-pre-line text-xs leading-5 text-slate-600 mt-2">{e.aiAccepted && e.improvedResponsibilities ? e.improvedResponsibilities : e.responsibilities}</p></div>)}</ResumeSection>}{data.education.length > 0 && <ResumeSection title="Education">{data.education.map((e) => <div key={e.id} className="mb-3"><div className="flex justify-between"><div><p className="text-sm font-bold">{e.qualification || 'Qualification'}</p><p className="text-xs text-brand-700 font-semibold">{e.institution || 'Institution'}</p></div><span className="text-[10px] text-slate-500">{e.startDate} – {e.endDate}</span></div>{e.description && <p className="text-xs text-slate-600 mt-1">{e.description}</p>}{e.achievements && <p className="text-xs text-slate-600 mt-1">{e.achievements}</p>}</div>)}</ResumeSection>}{data.skills.length > 0 && <ResumeSection title="Skills"><div className="flex flex-wrap gap-1.5">{data.skills.map((s) => <span key={s.id} className="text-xs text-slate-600">{s.name}{s.id !== data.skills[data.skills.length - 1].id ? ' ·' : ''}</span>)}</div></ResumeSection>}{data.certificates.length > 0 && <ResumeSection title="Certifications">{data.certificates.map((c) => <p key={c.id} className="text-xs text-slate-600 mb-1"><strong>{c.name}</strong>{c.issuer && ` — ${c.issuer}`}</p>)}</ResumeSection>}{data.projects.length > 0 && <ResumeSection title="Projects">{data.projects.map((p) => <div key={p.id} className="mb-2"><p className="text-xs font-bold">{p.name}</p><p className="text-xs text-slate-600">{p.description}</p></div>)}</ResumeSection>}</div></div>; }
function ResumeSection({ title, children }: { title: string; children: ReactNode }) { return <section className="mt-5"><h2 className="text-xs font-bold uppercase tracking-[0.18em] text-brand-700 border-b border-slate-200 pb-1.5 mb-3">{title}</h2>{children}</section>; }
function PreviewModal({ onClose }: { onClose: () => void }) { const { data, setTemplate, toggleChecklist } = useResume(); const all = data.checklist.every(Boolean); const [zoom, setZoom] = useState(100); return <div className="fixed inset-0 z-50 bg-slate-950/70 flex items-center justify-center p-3 sm:p-6"><div className="bg-slate-100 rounded-2xl w-full max-w-6xl h-full max-h-[94vh] flex flex-col overflow-hidden animate-scale-in"><div className="bg-white px-4 sm:px-6 py-4 border-b border-slate-200 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><button className="btn-ghost p-2" onClick={onClose}><X size={19} /></button><div><h2 className="font-bold">Resume preview</h2><p className="text-xs text-slate-500">Live preview · updates as you edit</p></div></div><div className="flex items-center gap-2"><select className="input-field py-2 w-auto text-sm" value={data.template} onChange={(e) => setTemplate(e.target.value as ResumeTemplate)}><option value="modern">Modern template</option><option value="classic">Classic template</option><option value="minimal">Minimal template</option></select><button className="btn-secondary p-2.5" onClick={() => setZoom((z) => Math.max(70, z - 10))} aria-label="Zoom out"><Minus size={16} /></button><span className="text-xs font-semibold w-9 text-center">{zoom}%</span><button className="btn-secondary p-2.5" onClick={() => setZoom((z) => Math.min(130, z + 10))} aria-label="Zoom in"><Plus size={16} /></button></div></div><div className="flex-1 overflow-auto p-4 sm:p-8"><div className="mx-auto bg-white shadow-elevated max-w-3xl" style={{ transform: `scale(${zoom / 100})`, transformOrigin: 'top center', marginBottom: `${(zoom - 100) * 5}px` }}><ResumePreview /></div></div><div className="bg-white border-t border-slate-200 px-4 sm:px-6 py-3 flex flex-col sm:flex-row items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs text-slate-500"><ShieldCheck size={15} className="text-success-600" /> {all ? 'Validation complete — ready to export' : 'Complete the validation checklist before exporting'}</div><div className="flex gap-2"><button className="btn-secondary text-sm" onClick={() => window.print()}><Printer size={15} /> Print</button><button className="btn-primary text-sm" disabled={!all} onClick={() => window.print()}><Download size={15} /> Download PDF</button></div></div></div></div>; }

function ATS() { const { data, setAtsResult } = useResume(); const [loading, setLoading] = useState(false); const [jd, setJd] = useState(data.jobTarget.jobDescription); const { navigate } = useRouter(); const result = data.atsResult; const run = async () => { if (!jd.trim()) return; setLoading(true); setAtsResult(await optimizeATS(data, jd)); setLoading(false); }; return <><PageHeader eyebrow="Career intelligence" title="ATS Optimizer" description="Understand how well your resume aligns with a target job description — without keyword stuffing." /><main className="section-container py-10"><div className="grid lg:grid-cols-[.8fr_1.2fr] gap-6"><div className="card p-6 h-fit"><SectionTitle icon={Search} title="Target job description" description="Paste the job posting you want to compare against." /><textarea className="input-field" rows={14} value={jd} onChange={(e) => setJd(e.target.value)} placeholder="Paste the full job description here..." /><button className="btn-primary w-full mt-4" onClick={run} disabled={!jd.trim() || loading}>{loading ? <Loader2 size={16} className="animate-spin" /> : <BarChart3 size={16} />} Run ATS Check</button>{!jd.trim() && <p className="text-xs text-warning-700 mt-3 flex gap-1"><AlertCircle size={13} /> A job description is required.</p>}</div><div>{!result ? <EmptyState icon={BarChart3} title="Your ATS estimate will appear here" description="Paste a target job description and run a check to see matching keywords and practical recommendations." action={<button className="btn-secondary text-sm" onClick={() => navigate('builder')}><Pencil size={15} /> Edit resume first</button>} /> : <div className="space-y-6 animate-fade-in"><div className="card p-6"><div className="flex flex-col sm:flex-row sm:items-center justify-between gap-5"><div><div className="flex items-center gap-2"><h2 className="text-lg font-bold">ATS compatibility score</h2><DemoBadge /></div><p className="text-sm text-slate-500 mt-2">An estimate based on your resume and this job description.</p></div><div className="relative w-28 h-28"><svg viewBox="0 0 36 36" className="w-full h-full -rotate-90"><path className="text-slate-100" stroke="currentColor" strokeWidth="3.5" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" /><path className={result.score >= 75 ? 'text-success-500' : result.score >= 55 ? 'text-warning-500' : 'text-error-500'} stroke="currentColor" strokeWidth="3.5" strokeLinecap="round" fill="none" strokeDasharray={`${result.score}, 100`} d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" /></svg><span className="absolute inset-0 flex items-center justify-center font-bold text-xl">{result.score}</span></div></div><div className="mt-4 p-3 rounded-lg bg-warning-50 border border-warning-100 text-xs text-warning-900 flex gap-2"><Info size={15} className="flex-shrink-0" /> This is an estimate, not a guarantee that a real employer’s ATS will accept your resume.</div></div><div className="grid md:grid-cols-2 gap-6"><KeywordCard title="Matching keywords" items={result.matchedKeywords} tone="success" /><KeywordCard title="Missing or underrepresented" items={result.missingKeywords} tone="warning" /></div><div className="card p-6"><SectionTitle icon={Lightbulb} title="Recommendations" /><div className="space-y-3">{result.recommendations.map((r) => <div key={r} className="flex gap-3 items-start p-3 rounded-lg bg-slate-50"><CheckCircle2 size={17} className="text-brand-600 mt-0.5 flex-shrink-0" /><p className="text-sm text-slate-700">{r}</p></div>)}</div></div></div>}</div></div></main></>; }
function KeywordCard({ title, items, tone }: { title: string; items: string[]; tone: 'success' | 'warning' }) { return <div className="card p-6"><h3 className="font-bold text-sm">{title}</h3>{items.length ? <div className="flex flex-wrap gap-2 mt-4">{items.map((x) => <span key={x} className={`badge ${tone === 'success' ? 'bg-success-50 text-success-700' : 'bg-warning-50 text-warning-700'}`}>{tone === 'success' ? <Check size={12} /> : <AlertCircle size={12} />}{x}</span>)}</div> : <p className="text-sm text-slate-400 mt-3">No keywords detected.</p>}</div>; }

function Assistant() { const { data } = useResume(); const [messages, setMessages] = useState<ChatMessage[]>([{ id: 'welcome', role: 'assistant', content: "Hello! I'm the CareerCraft Career Assistant. I can help with resumes, interviews, cover letters, ATS questions, job descriptions, and career strategy. What would you like help with today?", timestamp: Date.now() }]); const [input, setInput] = useState(''); const [loading, setLoading] = useState(false); const prompts = ['How can I improve my resume?', 'Help me prepare for an IT interview.', 'Improve this experience description.', 'What skills should I highlight for this role?', 'Explain what ATS means.']; const send = async (text = input) => { if (!text.trim() || loading) return; const message: ChatMessage = { id: `u-${Date.now()}`, role: 'user', content: text.trim(), timestamp: Date.now() }; setMessages((m) => [...m, message]); setInput(''); setLoading(true); const reply = await careerAssistantReply(message.content, data); setMessages((m) => [...m, { id: `a-${Date.now()}`, role: 'assistant', content: reply, timestamp: Date.now() }]); setLoading(false); }; return <><PageHeader eyebrow="Your career co-pilot" title="CareerCraft Career Assistant" description="Practical general guidance for resumes, applications, interviews, and career decisions. The Demo AI does not know facts beyond what you share." /><main className="section-container py-10"><div className="grid lg:grid-cols-[1fr_300px] gap-6 max-w-5xl mx-auto"><div className="card overflow-hidden flex flex-col min-h-[620px]"><div className="p-5 border-b border-slate-100 flex items-center justify-between"><div className="flex items-center gap-3"><span className="w-10 h-10 rounded-xl bg-brand-100 text-brand-700 flex items-center justify-center"><Bot size={21} /></span><div><h2 className="font-bold">CareerCraft Career Assistant</h2><p className="text-xs text-slate-500 mt-1 flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-success-500" /> Demo AI Mode</p></div></div><button className="btn-ghost p-2" onClick={() => setMessages([messages[0]])} aria-label="Clear conversation"><RefreshCw size={16} /></button></div><div className="flex-1 p-5 space-y-5 overflow-y-auto scrollbar-thin max-h-[470px]">{messages.map((m) => <div key={m.id} className={`flex gap-3 ${m.role === 'user' ? 'justify-end' : ''}`}><div className={`max-w-[85%] rounded-2xl px-4 py-3 ${m.role === 'user' ? 'bg-brand-600 text-white rounded-br-md' : 'bg-slate-100 text-slate-700 rounded-bl-md'}`}><p className="text-sm leading-6 whitespace-pre-line">{m.content}</p>{m.role === 'assistant' && <span className="badge bg-white/70 text-brand-700 mt-3"><Sparkles size={11} /> Demo AI Output</span>}</div></div>)}{loading && <div className="flex gap-3"><div className="bg-slate-100 rounded-2xl rounded-bl-md px-4 py-3 flex items-center gap-2"><Loader2 size={15} className="animate-spin text-brand-600" /><span className="text-sm text-slate-500">Thinking...</span></div></div>}</div><div className="p-4 border-t border-slate-100"><div className="flex gap-2"><input className="input-field" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') void send(); }} placeholder="Ask a career question..." /><button className="btn-primary px-3" onClick={() => void send()} disabled={!input.trim() || loading} aria-label="Send message"><Send size={17} /></button></div></div></div><div className="card p-5 h-fit"><div className="flex items-center gap-2"><Lightbulb size={17} className="text-warning-600" /><h3 className="font-bold text-sm">Try asking</h3></div><div className="space-y-2 mt-4">{prompts.map((p) => <button key={p} onClick={() => void send(p)} className="w-full text-left p-3 rounded-lg border border-slate-100 text-sm text-slate-600 hover:border-brand-200 hover:bg-brand-50 hover:text-brand-800 transition-colors">{p}</button>)}</div><div className="mt-5 p-3 rounded-lg bg-warning-50 border border-warning-100 text-xs leading-5 text-warning-900"><ShieldCheck size={14} className="inline mr-1" /> General advice is not a substitute for professional guidance. Verify important information.</div></div></div></main></>; }

function Templates() { const { data, setTemplate } = useResume(); const templates: { id: ResumeTemplate; name: string; text: string; best: string }[] = [{ id: 'modern', name: 'Modern', text: 'Clean contemporary design with a confident color accent.', best: 'Tech, startups, creative roles' }, { id: 'classic', name: 'Classic', text: 'Traditional professional layout with timeless typography.', best: 'Corporate, finance, established teams' }, { id: 'minimal', name: 'Minimal', text: 'Simple, highly readable design with strong typography.', best: 'Any role, maximum clarity' }]; return <><PageHeader eyebrow="Make a strong first impression" title="Professional templates" description="Choose a layout that makes your information easy to scan and remember." /><main className="section-container py-10"><div className="grid md:grid-cols-3 gap-6">{templates.map((t) => <div key={t.id} className={`card overflow-hidden ${data.template === t.id ? 'ring-2 ring-brand-500' : ''}`}><div className="bg-slate-50 p-7 h-72 flex items-start justify-center"><div className={`bg-white w-48 min-h-[235px] shadow-card p-4 ${t.id === 'classic' ? 'font-serif' : ''}`}><div className={`h-2.5 rounded w-20 ${t.id === 'modern' ? 'bg-brand-600' : 'bg-slate-700'}`} /><div className="h-1.5 bg-slate-200 rounded w-28 mt-2" /><div className="h-px bg-slate-200 mt-4" /><div className="h-1.5 bg-brand-100 rounded w-16 mt-4" /><div className="h-1 bg-slate-100 rounded w-full mt-2" /><div className="h-1 bg-slate-100 rounded w-11/12 mt-1.5" /><div className="h-1 bg-slate-100 rounded w-full mt-1.5" /><div className="h-1.5 bg-brand-100 rounded w-20 mt-5" /><div className="h-1 bg-slate-100 rounded w-full mt-2" /><div className="h-1 bg-slate-100 rounded w-10/12 mt-1.5" /></div></div><div className="p-5"><div className="flex justify-between items-center"><h3 className="font-bold">{t.name}</h3>{data.template === t.id && <span className="badge bg-success-50 text-success-700"><Check size={12} /> Active</span>}</div><p className="text-sm text-slate-500 mt-2 leading-6">{t.text}</p><p className="text-xs text-slate-400 mt-3">Best for: {t.best}</p><button className={`w-full mt-5 ${data.template === t.id ? 'btn-secondary' : 'btn-primary'}`} onClick={() => setTemplate(t.id)}>{data.template === t.id ? 'Selected' : 'Use this template'}</button></div></div>)}</div><div className="mt-8 card p-6 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4"><div><h3 className="font-bold">Want to see your resume in context?</h3><p className="text-sm text-slate-500 mt-1">Open the live preview to switch designs instantly.</p></div><button className="btn-primary" onClick={() => document.querySelector<HTMLButtonElement>('[aria-label="Open preview"]')?.click()}><FileText size={16} /> Preview resume</button></div></main></>; }

function InfoPage({ route }: { route: 'prompt-strategy' | 'productivity' | 'responsible-ai' | 'about' }) { const content = { 'prompt-strategy': { eyebrow: 'Work smarter with AI', title: 'Prompt strategy', description: 'Better inputs create more relevant, reliable suggestions — especially when your facts matter.', icon: Lightbulb }, productivity: { eyebrow: 'Make time for what matters', title: 'Productivity, without shortcuts', description: 'CareerCraft AI reduces repetitive work so you can spend more time reviewing, improving, and applying.', icon: Clock3 }, 'responsible-ai': { eyebrow: 'Trust comes first', title: 'Responsible AI', description: 'AI can help with wording and structure. It cannot verify your life story for you.', icon: ShieldCheck }, about: { eyebrow: 'Why CareerCraft AI exists', title: 'Built for authentic career growth', description: 'A practical career toolkit for people at every stage of their journey.', icon: BriefcaseBusiness } }[route]; return <><PageHeader eyebrow={content.eyebrow} title={content.title} description={content.description} /><main className="section-container py-10 max-w-5xl"><div className="grid lg:grid-cols-[1fr_280px] gap-8"><div className="space-y-6">{route === 'prompt-strategy' && <><InfoBlock icon={Lightbulb} title="The structure of an effective prompt"><p>Use this structure to guide AI toward useful, controlled output:</p><div className="grid sm:grid-cols-3 gap-3 mt-4">{['Role','Context','Task','Requirements','Constraints','Output format'].map((x) => <div key={x} className="rounded-xl bg-brand-50 border border-brand-100 p-4 text-center"><p className="text-sm font-bold text-brand-800">{x}</p></div>)}</div></InfoBlock><div className="grid md:grid-cols-2 gap-5"><PromptCard title="Basic prompt" text="Improve my resume summary." tone="slate" /><PromptCard title="Improved prompt" text="You are a professional career writing assistant. Improve the following resume summary for a junior IT role. Preserve all factual information provided by the user. Do not invent qualifications, experience, achievements, or technologies. Make the summary concise, professional, ATS-friendly, and easy to read. Return one improved version followed by three short improvement notes." tone="brand" /></div><InfoBlock icon={TrendingUp} title="Test, refine, compare"><p>Prompts can be tested and refined. Add the role you’re targeting, the audience, what must stay unchanged, and the exact format you want back. Specific constraints make it easier to review the result.</p></InfoBlock></>}{route === 'productivity' && <><div className="grid sm:grid-cols-2 gap-5"><TimeCard title="Traditional resume creation" value="3–5 hours" icon={Clock3} /><TimeCard title="AI-assisted creation" value="30–60 min" icon={Zap} accent /></div><InfoBlock icon={BarChart3} title="Illustrative time-saving areas"><div className="space-y-4 mt-4">{[['Writing','Drafting and strengthening wording'],['Editing','Spotting repetition and clarity gaps'],['Job description analysis','Finding relevant themes to review'],['ATS checking','Reviewing alignment opportunities'],['Formatting','Applying a consistent structure'],['Customization','Adapting your story to a target role']].map(([x, y]) => <div key={x} className="flex items-center gap-4"><span className="w-32 text-sm font-semibold">{x}</span><div className="flex-1 h-2 bg-slate-100 rounded-full"><div className="h-full bg-brand-500 rounded-full" style={{ width: `${45 + x.length * 5}%` }} /></div><span className="text-xs text-slate-400">{y}</span></div>)}</div></InfoBlock><div className="p-5 rounded-xl bg-accent-50 border border-accent-100 text-accent-900"><p className="font-semibold">AI does not replace human judgment.</p><p className="text-sm mt-1 leading-6">It reduces repetitive work so users can spend more time reviewing, improving, and applying.</p></div></>}{route === 'responsible-ai' && <><div className="p-6 rounded-2xl bg-warning-50 border border-warning-200 text-warning-950"><div className="flex gap-3"><ShieldCheck size={24} className="flex-shrink-0" /><p className="font-bold leading-6">AI-generated suggestions are recommendations, not verified facts. Always review and validate your resume before submitting it to an employer.</p></div></div><div className="grid sm:grid-cols-2 gap-5">{[['AI limitations','AI can misunderstand information or produce inaccurate suggestions.'],['Hallucinations','AI may generate information that sounds convincing but is incorrect.'],['Human review','Review AI-generated content before using it.'],['Bias','Career suggestions may contain biases based on training data.'],['Privacy','Avoid entering unnecessary sensitive information.'],['Authenticity','Only claim skills, qualifications, achievements, and experience that are genuinely yours.'],['ATS limitations','ATS scores are estimates and do not guarantee employment.']].map(([t, d]) => <div key={t} className="card p-5"><h3 className="font-bold">{t}</h3><p className="text-sm text-slate-500 leading-6 mt-2">{d}</p></div>)}</div></>}{route === 'about' && <><InfoBlock icon={AlertCircle} title="The problem"><p>Job seekers spend significant time creating resumes, rewriting experience descriptions, researching job requirements, and formatting documents — often while trying to make their story sound like themselves.</p></InfoBlock><InfoBlock icon={Sparkles} title="The solution"><p>CareerCraft AI combines AI-assisted writing, resume building, job description analysis, ATS guidance, and professional templates in one focused platform.</p></InfoBlock><div className="card p-6"><h2 className="text-lg font-bold">Built for</h2><div className="flex flex-wrap gap-2 mt-4">{['Students','Graduates','Internship applicants','Entry-level job seekers','Professionals','Career switchers'].map((x) => <span key={x} className="badge bg-brand-50 text-brand-700">{x}</span>)}</div><p className="text-slate-600 leading-7 mt-5">CareerCraft AI helps users create stronger resumes faster while keeping them in control of the final content.</p></div></>}</div><aside className="card p-6 h-fit"><span className="w-11 h-11 rounded-xl bg-brand-50 text-brand-600 flex items-center justify-center"><content.icon size={21} /></span><h3 className="font-bold mt-5">Your information stays yours</h3><p className="text-sm text-slate-500 leading-6 mt-2">Only provide information necessary for creating your resume. Review every suggestion before accepting it.</p></aside></div></main></>; }
function InfoBlock({ icon: Icon, title, children }: { icon: typeof Sparkles; title: string; children: ReactNode }) { return <div className="card p-6"><div className="flex items-center gap-3"><span className="w-9 h-9 rounded-lg bg-brand-50 text-brand-600 flex items-center justify-center"><Icon size={18} /></span><h2 className="text-lg font-bold">{title}</h2></div><div className="mt-4 text-slate-600 leading-7 text-sm">{children}</div></div>; }
function PromptCard({ title, text, tone }: { title: string; text: string; tone: 'slate' | 'brand' }) { return <div className={`rounded-2xl p-5 border ${tone === 'brand' ? 'bg-brand-50 border-brand-100' : 'bg-slate-50 border-slate-200'}`}><p className="text-xs uppercase tracking-wider font-bold text-slate-500">{title}</p><p className="mt-3 text-sm leading-6 text-slate-700">“{text}”</p><div className="mt-4 badge bg-white text-slate-600">{tone === 'brand' ? <><Check size={12} /> More controlled</> : <><AlertCircle size={12} /> Less controlled</>}</div></div>; }
function TimeCard({ title, value, icon: Icon, accent = false }: { title: string; value: string; icon: typeof Clock3; accent?: boolean }) { return <div className={`card p-6 ${accent ? 'border-accent-200 bg-accent-50/40' : ''}`}><span className={`w-10 h-10 rounded-xl flex items-center justify-center ${accent ? 'bg-accent-100 text-accent-700' : 'bg-slate-100 text-slate-600'}`}><Icon size={20} /></span><p className="text-xs font-semibold uppercase tracking-wider text-slate-500 mt-5">{title}</p><p className="text-3xl font-bold mt-2">{value}</p><p className="text-xs text-slate-400 mt-2">Illustrative estimate</p></div>; }

export default function App() { const { route } = useRouter(); const content: Record<PageRoute, ReactNode> = { home: <Home />, dashboard: <Dashboard />, builder: <Builder />, assistant: <Assistant />, ats: <ATS />, templates: <Templates />, 'prompt-strategy': <InfoPage route="prompt-strategy" />, productivity: <InfoPage route="productivity" />, 'responsible-ai': <InfoPage route="responsible-ai" />, about: <InfoPage route="about" /> }; return <div className="min-h-screen bg-white"><Navbar /><div key={route} className="animate-fade-in">{content[route]}</div>{route !== 'builder' && <Footer />}</div>; }
